    heap = []
    heapq.heappush(heap, (0, 0))
    dist = {0: 0}
    found = False
    result = -1

    while heap:
        cost, state = heapq.heappop(heap)
        if state in dist and dist[state] < cost:
            continue
        bits = bin(state).count('1')
        if bits in (0, 1) and cost > 0:
            result = cost
            found = True
            break
