    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    R = int(input[2])
    S = int(input[3])
    P = int(input[4])
    T = input[5]

    # Mapping from 'R', 'P', 'S' to their points
    point_map = {'R': R, 'P': P, 'S': S}

    # Initialize DP
    dp = [{} for _ in range(N+1)]

    # For the first K rounds, no constraint
    for j in range(1, K+1):
        current_char = T[j-1]
        for c in ['R', 'P', 'S']:
            if j == 1:
                score = point_map[c] if (c == 'R' and current_char == 'S') or (c == 'P' and current_char == 'R') or (c == 'S' and current_char == 'P') else 0
            else:
                max_prev = max(dp[j-1].values())
                score = max_prev + (point_map[c] if (c == 'R' and current_char == 'S') or (c == 'P' and current_char == 'R') or (c == 'S' and current_char == 'P') else 0)
            dp[j][c] = score

    # For rounds K+1 to N, compute based on j-K
    for j in range(K+1, N+1):
        current_char = T[j-1]
        # Consider all possible previous choices (c_prev) that are not equal to current choice
        for c_current in ['R', 'P', 'S']:
            max_score = 0
            for c_prev in ['R', 'P', 'S']:
                if c_prev != c_current:
                    prev_score = dp[j-K][c_prev]
                    # Calculate the score for current choice
                    if (c_current == 'R' and current_char == 'S') or (c_current == 'P' and current_char == 'R') or (c_current == 'S' and current_char == 'P'):
                        score = prev_score + point_map[c_current]
                    else:
                        score = prev_score
                    if score > max_score:
                        max_score = score
            dp[j][c_current] = max_score

    # The answer is the maximum value in dp[N]
    print(max(dp[N].values()))

