    k_min = (N + M - 1) // M
    found = False
    for k in range(k_min, N + 1):
        if k > N:
            break
        if k <= N <= k * M:
            s_sum = 0
            sequence = []
            possible = True
            for i in range(1, k + 1):
                a = max(i, N - (k - i) * M)
                b = min(N - (k - i), s_sum + M)
                if a > b:
                    possible = False
                    break
                x_min = max(1, a - s_sum)
                x_max = min(M, b - s_sum)
                if x_min > x_max:
                    possible = False
                    break
                x = x_min
                new_sum = s_sum + x
                if new_sum > N:
                    possible = False
                    break
                if S[new_sum] == '1':
                    possible = False
                    break
                remaining = k - i - 1
                required = N - new_sum
                if required < remaining:
                    possible = False
                    break
                if required > remaining * M:
                    possible = False
                    break
