    n = int(n)
    m = int(m)
    s = s.replace(' ', '')  # Ensure no spaces in S

    game_over = [False] * (n + 1)
    for i in range(n + 1):
        if s[i] == '1':
            game_over[i] = True

    INF = float('inf')
    d = [INF] * (n + 1)
    d[0] = 0

    dq = deque()
    dq.append(0)

    for i in range(1, n + 1):
        if game_over[i]:
            d[i] = INF
            continue

        # Remove indices out of the window [i-M, i-1]
        while dq and dq[0] < i - m:
            dq.popleft()

        # Remove game over squares from the front
        while dq and game_over[dq[0]]:
            dq.popleft()

        if not dq:
            d[i] = INF
        else:
            d[i] = d[dq[0]] + 1

        # Maintain deque in order of increasing d[i]
        while dq and d[i] <= d[dq[-1]]:
            dq.pop()
        dq.append(i)

    if d[n] == INF:
        print(-1)
        return

    # Reconstruct the sequence
    sequence = []
    i = n
    while i > 0:
        found = False
        for x in range(m, 0, -1):
            prev = i - x
            if prev < 0:
                continue
            if game_over[prev]:
                continue
            if d[prev] + 1 == d[i]:
                sequence.append(x)
                i = prev
                found = True
                break
        if not found:
            print(-1)
            return

    # Reverse to get the correct order
    sequence = sequence[::-1]
    print(' '.join(map(str, sequence)))

