import heapq

def compute_min_steps(N, M, S):
    visited = {}
    heap = []
    heapq.heappush(heap, (0, 0))
    visited[0] = 0

    while heap:
        current_sum, steps = heapq.heappop(heap)

        if current_sum == N:
            return steps

        if steps > visited.get(current_sum, float('inf')):
            continue

        for x in range(1, M + 1):
            new_sum = current_sum + x
            if new_sum > N:
                continue
            if S[new_sum] == '1':
                continue
            if new_sum not in visited or steps + 1 < visited.get(new_sum, float('inf')):
                visited[new_sum] = steps + 1
                heapq.heappush(heap, (new_sum, steps + 1))

    return -1

def find_lex_smallest_sequence(N, M, S, k):
    current_sum = 0
    sequence = []
    for _ in range(k):
        for x in range(1, M + 1):
            new_sum = current_sum + x
            if new_sum > N:
                continue
            if S[new_sum] == '1':
                continue
            remaining_sum = N - new_sum
            remaining_steps = k - len(sequence) - 1
            minimal_required = (remaining_sum + M - 1) // M
            if remaining_steps >= minimal_required:
                sequence.append(x)
                current_sum = new_sum
                break
        else:
            return None
    if current_sum != N:
        return None
    return sequence

