def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    M = int(input[idx])
    idx += 1

    edges = []
    adj = [[] for _ in range(N + 1)]  # 1-based indexing

    for _ in range(M):
        a = int(input[idx])
        idx += 1
        b = int(input[idx])
        idx += 1
        c = int(input[idx])
        idx += 1
        edges.append((a, b, c))
        adj[a].append((b, c))
        adj[b].append((a, c))

    # Compute all-pairs shortest paths using Dijkstra's algorithm
    INF = float('inf')
    dist = [[INF] * (N + 1) for _ in range(N + 1)]

    for u in range(1, N + 1):
        dist_u = dist[u]
        dist_u[u] = 0
        heap = []
        heapq.heappush(heap, (0, u))
        visited = [False] * (N + 1)
        while heap:
            d, v = heapq.heappop(heap)
            if visited[v]:
                continue
            visited[v] = True
            for neighbor, weight in adj[v]:
                if dist_u[neighbor] > d + weight:
                    dist_u[neighbor] = d + weight
                    heapq.heappush(heap, (dist_u[neighbor], neighbor))

    count = 0

    for a, b, c in edges:
        used = False
        for u in range(1, N + 1):
            for v in range(1, N + 1):
                if u == v:
                    continue
                # Check if a to b is part of the path
                if dist[u][a] + c + dist[b][v] == dist[u][v]:
                    used = True
                    break
                # Check if b to a is part of the path
                if dist[u][b] + c + dist[a][v] == dist[u][v]:
                    used = True
                    break
            if used:
                break
        if not used:
            count += 1

    print(count)

