    graph = [[INF] * N for _ in range(N)]
    for a, b, c in edges:
        graph[a][b] = c
        graph[b][a] = c  # Since the graph is undirected

    # Floyd-Warshall algorithm to find all-pairs shortest paths
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if graph[i][k] + graph[k][j] < graph[i][j]:
                    graph[i][j] = graph[i][k] + graph[k][j]

    count = 0
