from collections import deque

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(H):
        row = list(map(int, sys.stdin.readline().split()))
        grid.append(row)

    # Compute initial parities
    parities = [[a % 2 for a in row] for row in grid]
    odd_cells = [(i, j) for i in range(H) for j in range(W) if parities[i][j] == 1]

    # If there are no odd cells, output 0
    if not odd_cells:
        print(0)
        return

    # BFS to find maximum matching
    visited = [[False for _ in range(W)] for _ in range(H)]
    q = deque()
    for (i, j) in odd_cells:
        if not visited[i][j]:
            visited[i][j] = True
            q.append((i, j))

    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Each node in the queue will store its position and the cell it's paired with
    paired = {}
    max_pairs = 0

    while q:
        i, j = q.popleft()
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W:
                if not visited[ni][nj] and parities[ni][nj] == 1:
                    visited[ni][nj] = True
                    paired[(i, j)] = (ni, nj)
                    paired[(ni, nj)] = (i, j)
                    max_pairs += 1
                    q.append((ni, nj))
                    break

    # Now, collect all the moves
    moves = []
    for (i, j) in odd_cells:
        if (i, j) in paired:
            ni, nj = paired[(i, j)]
            moves.append((i+1, j+1, i+1, j+1))
            moves.append((ni+1, nj+1, ni+1, nj+1))

    # Output the result
    print(len(moves))
    for move in moves:
        print(' '.join(map(str, move)))

