        pair_U = [-1] * len(U)
        pair_V = [-1] * len(V)
        dist = [0] * len(U)

        def bfs():
            queue = deque()
            for u in range(len(U)):
                if pair_U[u] == -1:
                    dist[u] = 0
                    queue.append(u)
                else:
                    dist[u] = float('inf')
