from collections import deque

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = []
    total = 0
    for _ in range(H):
        row = list(map(int, sys.stdin.readline().split()))
        grid.append(row)
        total += sum(row)

    target_even = H * W if total % 2 == 0 else H * W - 1
    current_even = sum(1 for row in grid for cell in row if cell % 2 == 0)

    if current_even == target_even:
        print(0)
        return

    # We need to find pairs of odd cells to flip
    # We'll use a queue to process cells
    q = deque()
    visited = [[False for _ in range(W)] for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] % 2 != 0 and not visited[i][j]:
                q.append((i, j))
                visited[i][j] = True

    operations = []
    while q:
        i, j = q.popleft()
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W:
                if grid[ni][nj] % 2 != 0 and not visited[ni][nj]:
                    visited[ni][nj] = True
                    q.append((ni, nj))

    # Now, we need to find a way to pair the odd cells
    # We'll process them in BFS order
    # Each time, take two adjacent odd cells and perform a move
    # We'll need to track which cells have been used
    used = [[False for _ in range(W)] for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] % 2 != 0 and not used[i][j]:
                q.append((i, j))
                used[i][j] = True

    count = 0
    while q:
        i, j = q.popleft()
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W:
                if grid[ni][nj] % 2 != 0 and not used[ni][nj]:
                    used[ni][nj] = True
                    count += 1
                    operations.append((i+1, j+1, ni+1, nj+1))
                    q.append((ni, nj))

    print(count)
    for op in operations:
        print(' '.join(map(str, op)))

