def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    players = [[] for _ in range(N)]
    for i in range(N):
        players[i] = list(map(int, input[idx:idx + N-1]))
        idx += N-1

    # For each player, their matches are in the given order
    # We need to find the minimal number of days such that each player's matches are scheduled in order
    # and no two matches of the same player are on the same day.

    # Each match is between two players, so we can represent it as a tuple (i, j) where i < j
    # But since the order matters, we need to track dependencies.

    # We can model this as a DAG where each node is a match, and edges represent dependencies.
    # The minimal number of days is the length of the longest path in this DAG.

    # However, for N=1000, this approach is not feasible. So we need a smarter way.

    # Instead, we can compute for each player the maximum number of matches they have to wait for before their next match can be scheduled.

    # For each player i, their matches are in the order of players[i][0], players[i][1], ..., players[i][N-2]
    # For each match mi (against players[i][k]), the opponent is j = players[i][k]
    # For j, their matches are in the order players[j][0], players[j][1], ..., players[j][N-2]
    # So, for mi to be scheduled, all matches of j before mj must be scheduled before mi.

    # The minimal number of days is the maximum, over all players, of the number of matches that a player has to play before their next match can be scheduled.

    # To compute this, for each player i, we can track the number of matches that their opponents have before the current match.

    # We can represent this as a list where for each player i, we track the maximum number of matches that any opponent j has before their match with i.

    # The minimal number of days is the maximum value in this list.

    # So, for each player i, for each match mi in their sequence, we look at the opponent j and see how many matches j has before mj. The maximum of these values across all mi is the minimal number of days.

    # Wait, but this might not capture all dependencies correctly. For example, if j has to wait for k, and k has to wait for l, etc., the dependencies can form a chain.

    # So, perhaps the minimal number of days is the maximum number of matches that any player has to play before their next match can be scheduled, considering the dependencies.

    # This can be computed by, for each player i, for each match mi in their sequence, count the number of matches that their opponent j has before mj, and take the maximum over all these counts.

    # So, for each player i, we can compute the maximum number of matches that any opponent j has before their match with i.

    # The minimal number of days is the maximum of these values across all players.

    # Let's implement this.

    max_days = 0

    for i in range(N):
        current_max = 0
        for k in range(len(players[i])):
            j = players[i][k]
            # For j, how many matches are before the match against i?
            # We need to find the position of i in j's list.
            pos_j = players[j].index(i)
            # The number of matches j has before this match is pos_j.
            current_max = max(current_max, pos_j)
        max_days = max(max_days, current_max)

    print(max_days if max_days != -1 else -1)

