from collections import defaultdict, deque

def main():
    n = int(sys.stdin.readline())
    sequences = []
    for _ in range(n):
        seq = list(map(int, sys.stdin.readline().split()))
        sequences.append(seq)

    # Create all matches
    matches = set()
    for i in range(n):
        player = i + 1
        for j in sequences[i]:
            if player < j:
                matches.add((player, j))
            else:
                matches.add((j, player))
    matches = list(matches)

    # Build the graph
    graph = defaultdict(list)
    for i in range(n):
        player = i + 1
        seq = sequences[i]
        player_matches = []
        for j in seq:
            if player < j:
                player_matches.append((player, j))
            else:
                player_matches.append((j, player))
        for k in range(len(player_matches) - 1):
            current = player_matches[k]
            next_match = player_matches[k + 1]
            graph[current].append(next_match)

    # Check for cycles using Kahn's algorithm
    in_degree = defaultdict(int)
    for match in matches:
        for neighbor in graph[match]:
            in_degree[neighbor] += 1

    queue = deque()
    for match in matches:
        if in_degree[match] == 0:
            queue.append(match)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(top_order) != len(matches):
        print(-1)
        return

    # Compute earliest days
    earliest_day = {match: 1 for match in matches}
    for u in top_order:
        for v in graph[u]:
            if earliest_day[v] < earliest_day[u] + 1:
                earliest_day[v] = earliest_day[u] + 1

    max_day = max(earliest_day.values())
    print(max_day)

