from functools import lru_cache

def main():
    import sys
    N, X = map(int, sys.stdin.readline().split())

    @lru_cache(maxsize=None)
    def count_patties(L, X):
        if X == 0:
            return 0
        if X == 1:
            return 0

        # Precompute the number of layers for each level up to L
        layers = [0] * (L + 1)
        layers[0] = 1
        for i in range(1, L + 1):
            layers[i] = 2 * layers[i - 1] + 3

        total_patty = 0
        remaining_X = X

        # The structure of a level-L burger: B, level L-1, P, level L-1, B
        components = [
            ('B', 1),
            ('level', L - 1, layers[L - 1]),
            ('P', 1),
            ('level', L - 1, layers[L - 1]),
            ('B', 1)
        ]

        for component in components:
            type_, count = component
            if remaining_X <= 0:
                break
            if type_ == 'B':
                if remaining_X >= count:
                    remaining_X -= count
                else:
                    return total_patty
            elif type_ == 'P':
                if remaining_X >= count:
                    total_patty += 1
                    remaining_X -= count
                else:
                    return total_patty
            else:
                if remaining_X >= count:
                    total_patty += count_patties(L - 1, count)
                    remaining_X -= count
                else:
                    total_patty += count_patties(L - 1, remaining_X)
                    remaining_X = 0
                    break

        return total_patty

    print(count_patties(N, X))

