import math

MOD = 10**9 + 7

def compute_sum(m, N):
    if m == 0:
        return 0
    q_max = int(math.isqrt(N))
    total = 0
    # Handle x <= q_max
    for x in range(1, min(q_max, m) + 1):
        total += N // x
        if total >= MOD:
            total -= MOD
    # Handle x > q_max
    for q in range(1, q_max + 1):
        l = N // q
        r = N // (q + 1)
        lower = r + 1
        upper = min(l, m)
        if lower > upper:
            continue
        count = upper - lower + 1
        add = q * count
        if add >= MOD:
            add -= MOD
        total += add
        if total >= MOD:
            total -= MOD
    return total % MOD

def main():
    N, K = map(int, sys.stdin.readline().split())
    if K == 1:
        print(N % MOD)
        return
    # Initialize dp_prev as a function that returns m for any m
    def dp_prev(m):
        return compute_sum(m, N)

    for _ in range(K-1):
        # Compute dp_current
        dp_current = {}
        for y in range(1, N+1):
            m = N // y
            if m == 0:
                val = 0
            else:
                val = dp_prev(m)
            dp_current[y] = val % MOD
        # Update dp_prev to be the new dp function
        def new_dp_prev(m):
            total = 0
            for y in range(1, N+1):
                if y > m:
                    continue
                m_val = N // y
                if m_val == 0:
                    continue
                total += dp_current[y]
                if total >= MOD:
                    total -= MOD
            return total % MOD
        dp_prev = new_dp_prev

    total = 0
    for y in range(1, N+1):
        m = N // y
        if m == 0:
            val = 0
        else:
            val = dp_prev(m)
        total = (total + val) % MOD
    print(total % MOD)

