def main():
    import sys
    a, b, x, y = map(int, sys.stdin.readline().split())
    start = f"A{a}"
    end = f"B{b}"

    # Initialize the graph
    graph = {}
    for i in range(1, 101):
        node_a = f"A{i}"
        node_b = f"B{i}"
        # Add corridor between A_i and B_i
        graph[node_a] = [(node_b, x)]
        graph[node_b] = [(node_a, x)]
        # Add staircase in A
        if i < 100:
            graph[node_a].append((f"A{i+1}", y))
        if i > 1:
            graph[node_a].append((f"A{i-1}", y))
        # Add staircase in B
        if i < 100:
            graph[node_b].append((f"B{i+1}", y))
        if i > 1:
            graph[node_b].append((f"B{i-1}", y))

    # Add cross-building corridors for i from 1 to 99: A_{i+1} connected to B_i
    for i in range(1, 100):
        node_a = f"A{i+1}"
        node_b = f"B{i}"
        graph[node_a].append((node_b, x))
        graph[node_b].append((node_a, x))

    # Dijkstra's algorithm to find the shortest path
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    heap = []
    heapq.heappush(heap, (0, start))

    while heap:
        current_cost, current_node = heapq.heappop(heap)
        if current_node == end:
            print(current_cost)
            return
        if current_cost > dist[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            new_cost = current_cost + weight
            if new_cost < dist[neighbor]:
                dist[neighbor] = new_cost
                heapq.heappush(heap, (new_cost, neighbor))

    # If end is not reachable (though problem constraints ensure it is)
    print(dist[end])

