    N = int(input[0])
    A = list(map(int, input[1:N+1]))

    # Compute overall GCD
    current_gcd = A[0]
    for num in A[1:]:
        current_gcd = math.gcd(current_gcd, num)
        if current_gcd == 1:
            break
    if current_gcd != 1:
        print("not coprime")
        return

    # Precompute smallest prime factors up to 1e6
    max_A = 10**6
    spf = list(range(max_A + 1))
    for i in range(2, int(math.isqrt(max_A)) + 1):
        if spf[i] == i:  # i is a prime
            for j in range(i * i, max_A + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Factorize each number and count primes
    prime_counts = defaultdict(int)
    for num in A:
        if num == 1:
            continue
        x = num
        factors = set()
        while x != 1:
            p = spf[x]
            factors.add(p)
            while x % p == 0:
                x = x // p
        for p in factors:
            prime_counts[p] += 1

    # Check if any prime appears in more than one number
    has_common_prime = any(count >= 2 for count in prime_counts.values())
    if has_common_prime:
        print("setwise coprime")
    else:
        print("pairwisecoprime")

