                    spf[j] = i

    # Function to get prime factors of a number
    def get_primes(x):
        if x == 1:
            return set()
        primes = set()
        while x != 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x = x // p
        return primes

    prime_counts = defaultdict(int)
    pairwise_coprime = True

    for a in A:
        if a == 1:
            continue
        primes = get_primes(a)
        for p in primes:
            prime_counts[p] += 1
            if prime_counts[p] >= 2:
                pairwise_coprime = False

    # Compute overall GCD
    overall_gcd = A[0]
    for num in A[1:]:
        overall_gcd = math.gcd(overall_gcd, num)
        if overall_gcd == 1:
            break

    if pairwise_coprime:
        print("pairwisecoprime")
    else:
        if overall_gcd == 1:
            print("setwisecoprime")
