def solve():
    import sys
    N = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    if N == 0:
        print("")
        return

    # We'll try to find a valid assignment
    # We can represent the assignment as a list of 'S' and 'W'
    # We'll start by assuming the first animal is a sheep and see if it leads to a valid assignment
    # Then, we'll try assuming the first animal is a wolf

    # Case 1: Assume S_1 is 'S'
    assignment = [''] * (N + 2)  # 1-based to N
    assignment[1] = 'S'
    valid = True
    for i in range(1, N + 1):
        # Get the triplet (i-1, i, i+1)
        a = assignment[i-1]
        b = assignment[i]
        c = assignment[i+1]
        if s[i-1] == 'o':
            # For 'o', the triplet must be (S,S,S) or (W,W,W) if b is S or W respectively
            if b == 'S':
                if not (a == 'S' and c == 'S'):
                    valid = False
                    break
            else:
                if not (a == 'W' and c == 'W'):
                    valid = False
                    break
        else:
            # For 'x', the triplet must be (S,W,S) or (W,S,W) if b is S or W respectively
            if b == 'S':
                if not (a == 'S' and c == 'W' or a == 'W' and c == 'S'):
                    valid = False
                    break
            else:
                if not (a == 'S' and c == 'S' or a == 'W' and c == 'W'):
                    valid = False
                    break
        # Update assignment[i+1]
        assignment[i+1] = assignment[i]

    if valid:
        print(''.join(assignment[1:N+1]))
        return

    # Case 2: Assume S_1 is 'W'
    assignment = [''] * (N + 2)
    assignment[1] = 'W'
    valid = True
    for i in range(1, N + 1):
        a = assignment[i-1]
        b = assignment[i]
        c = assignment[i+1]
        if s[i-1] == 'o':
            if b == 'S':
                if not (a == 'S' and c == 'S'):
                    valid = False
                    break
            else:
                if not (a == 'W' and c == 'W'):
                    valid = False
                    break
        else:
            if b == 'S':
                if not (a == 'W' and c == 'W' or a == 'S' and c == 'W'):
                    valid = False
                    break
            else:
                if not (a == 'S' and c == 'S' or a == 'W' and c == 'W'):
                    valid = False
                    break
        assignment[i+1] = assignment[i]

    if valid:
        print(''.join(assignment[1:N+1]))
        return

    # If neither case works, output -1
    print(-1)

