MOD = 10**8 + 7

def reduce(a, b):
    if a == 0 and b == 0:
        return (0, 0)
    g = math.gcd(abs(a), abs(b))
    a //= g
    b //= g
    if a == 0:
        if b < 0:
            b = -b
    else:
        if a < 0:
            a = -a
            b = -b
    return (a, b)

