            continue
        a, b = reduce(A, B)
        key = (a, b)
        if key in direction_counts:
            direction_counts[key] += 1
        else:
            direction_counts[key] = 1
    total_non_zero = 1
    processed = set()
    for d in list(direction_counts.keys()):
