    import sys
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1

    S = list(map(int, input[ptr:ptr+N]))
    ptr += N

    T = list(map(int, input[ptr:ptr+N]))
    ptr += N

    U = list(map(int, input[ptr:ptr+N]))
    ptr += N

    V = list(map(int, input[ptr:ptr+N]))
    ptr += N

    # Check necessary conditions
    possible = True
    for i in range(N):
        for j in range(N):
            if (S[i] == 0 and T[j] == 1) or (S[i] == 1 and T[j] == 0):
                if (S[i] == 0 and T[j] == 1):
                    if U[i] > V[j]:
                        possible = False
                elif (S[i] == 1 and T[j] == 0):
                    if V[j] > U[i]:
                        possible = False
    if not possible:
        print(-1)
        return

    # Construct the matrix
    matrix = [[0 for _ in range(N)] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if S[i] == 0 and T[j] == 0:
                matrix[i][j] = max(U[i], V[j])
            elif S[i] == 0 and T[j] == 1:
                matrix[i][j] = U[i]
            elif S[i] == 1 and T[j] == 0:
                matrix[i][j] = V[j]
            else:
                matrix[i][j] = min(U[i], V[j])

    # Check rows
    for i in range(N):
        if S[i] == 0:
            row = matrix[i]
            and_val = row[0]
            for num in row[1:]:
                and_val &= num
            if and_val != U[i]:
                possible = False
                break
        else:
            row = matrix[i]
            or_val = row[0]
            for num in row[1:]:
                or_val |= num
            if or_val != U[i]:
                possible = False
                break
    if not possible:
        print(-1)
        return

    # Check columns
    for j in range(N):
        col = [matrix[i][j] for i in range(N)]
        if T[j] == 0:
            and_val = col[0]
            for num in col[1:]:
                and_val &= num
            if and_val != V[j]:
                possible = False
                break
        else:
            or_val = col[0]
            for num in col[1:]:
                or_val |= num
            if or_val != V[j]:
                possible = False
                break
    if not possible:
        print(-1)
        return

    # Output the matrix
    for row in matrix:
        print(' '.join(map(str, row)))

